                          </div>
                        </div>
                      </div>
                      <div class="info-table-option">
                        <div class="info-option-tit">Twitter</div>
                        <div class="info-option-content">
                          <div class="info-content-main">
                            <div
                              class="info-social-option"
                              v-for="(item, index) of props.row.Twitter"
                              :key="index"
                            >{{item.Data}}</div>
                          </div>
                        </div>
                      </div>
                      <div class="info-table-option">
                        <div class="info-option-tit">Instagram</div>
                        <div class="info-option-content">
                          <div class="info-content-main">
                            <div
