              <el-table-column label="Facecbook" align="center">
                <template slot-scope="scope">
                  <div class="social-table-wrap">
                    <template v-for="(item, index) of scope.row.FaceBook">
                      <div
                        v-if="index < 3 && scope.row.FaceBook.length > 0"
                        class="social-table-option one-row"
