<script>
import { mapGetters, mapActions } from 'vuex'
export default {
  name: 'taskImport',
  inject: [
    // 接收祖先组件注入的依赖（打开分组弹窗的方法）
    'openAddGroup'
  ],
  data () {
    return {
      secondLoading: false,
      firstLoading: false,
      tableLoading: false,
      importStepOption: [],
      step: 'form',
      concatDataOption: [
        {
          label: '0个',
          value: 0
        },
        {
          label: '5个',
          value: 5
        }, {
          label: '10个',
          value: 10
        }, {
          label: '15个',
          value: 15
        }, {
          label: '20个',
          value: 20
        }, {
          label: '25个',
          value: 25
        }, {
          label: '30个',
          value: 30
        }, {
          label: '35个',
          value: 35
        }, {
          label: '40个',
          value: 40
        }, {
          label: '45个',
          value: 45
        }, {
          label: '50个',
          value: 50
        }
      ],
      page: {
        page: 1,
        num: 30,
        total: 0
      },
      table: [],
      isIndeterminateTable: false,
      excelHeadOption: {
        Url: [],
        Title: [],
        Description: [],
        Email: [],
        Facebook: [],
        Linkedin: [],
        Twitter: [],
        Instagram: []
      },
      excelHead: {
        FilePath: '',
        Url: '',
        Title: '',
        Description: '',
        Email: '',
        Facebook: '',
        Linkedin: '',
        Twitter: '',
        Instagram: ''
      },
      task: {
        groupId: '',
        taskName: ''
      },
      concatId: 0,
      importStep: ''
    }
  },
  methods: {
    ...mapActions(['taskDetailInfoDispatch']),
    handleSelectPath (e) {
      e.target.blur()
      this.firstLoading = true
      this.SharpObj.getImportExcelHeaderList(res => {
        this.firstLoading = false
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        this.excelHead.FilePath = res.Data.FilePath
        Object.assign(this.excelHeadOption, res.Data.ExcelHead)
      })
    },
    checkAllTable () {
      this.isIndeterminateTable = false
    },
    changePage (page) {
      this.page.page = page
    },
    handleTableChange (row) {
      let checkCount = 0
      for (let item of this.table) {
        item.IsCheck && checkCount++
      }
      if (checkCount > 0 && checkCount < this.table.length) {
        this.isIndeterminateTable = true
      } else {
        this.isIndeterminateTable = false
      }
    },
    handleGoNext () {
      let validate = this.$WmlValidator.validate([
        {
          value: this.task.taskName,
          rules: [
            {
              rule: 'isNonNull',
              errorMsg: '请输入任务名'
            }
          ]
        },
        {
          value: this.excelHead.FilePath,
          rules: [
            {
              rule: 'isNonNull',
              errorMsg: '请选择需要导入的文件'
            }
          ]
        },
        {
          value: this.task.groupId,
          rules: [
            {
              rule: 'isNonNull',
              errorMsg: '请选择任务分组'
            }
          ]
        }
      ])
      if (validate) {
        this.$WmlMsg(validate, 'warning')
        return
      }
      this.tableLoading = true
      this.SharpObj.getImportStep(res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        this.importStepOption = res.Data
        this.importStep = this.importStepOption[0].Value
        this.step = 'table'
      })
      let excelHead = JSON.parse(JSON.stringify(this.excelHead))
      delete excelHead.FilePath
      for (let key in excelHead) {
        if (excelHead[key] === '') {
          delete excelHead[key]
        }
      }
      this.SharpObj.getImportExcelData(JSON.stringify(excelHead), res => {
        res = JSON.parse(res)
        this.tableLoading = false
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        this.table = res.Data
        this.page.total = this.table.length
      })
    },
    doSave () {
      this.secondLoading = true
      let table = []
      for (let item of this.table) {
        item.IsCheck && table.push(item)
      }
      this.concatId = this.importStep ? this.concatId : 0
      this.SharpObj.isCanImport(JSON.stringify(table), this.importStep, this.concatId, this.task.groupId, this.task.taskName, async res => {
        this.secondLoading = false
        if (res.Code !== 2) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        if (!await this.$WmlConfirm(res.Msg)) { return }
        this.secondLoading = true
        this.SharpObj.importExcelData(res => {
          this.secondLoading = false
          res = JSON.parse(res)
          if (res.Code !== 0) {
            this.$WmlMsg(res.Msg, 'warning')
            return
          }

          for (let item of this.TaskListGetter) {
            if (item.Id === res.Data.GroupId) {
              this.taskDetailInfoDispatch({ groupName: item.GroupName, taskName: res.Data.TaskName })
              item.Task.push(res.Data)
              break
            }
          }
          this.$WmlMsg('导入成功！')
          this.$to({ path: '/marketing/index/' + res.Data.Id })
        })
      })
    }
  },
  created () {
    // this.init()
  },
  mounted () {
    // 创建任务组成功自动选择该任务组
    this.$bus.$on('selectGroup', id => {
      this.task.groupId = id
    })
  },
  computed: {
    ...mapGetters(['TaskListGetter']),
    checkAll: {
      get: function () {
        if (this.table.length === 0) {
          return false
        }
        for (let item of this.table) {
          if (!item.IsCheck) {
            return false
          }
        }
        return true
      },
      set: function (bool) {
        for (let i = 0; i < this.table.length; i++) {
          this.$set(this.table[i], 'IsCheck', bool)
        }
      }
    },
    tableData: {
      get: function () {
        let newTableData = this.table.slice(this.page.num * (this.page.page - 1), this.page.num * this.page.page)
        return newTableData
      },
      set: function () { }
    }
  },
  beforeDestroy () {
    this.table = null
  }
}
</script>

