 <template>
  <div class="taskCreate-main" v-loading.body="loading">
    <el-form ref="form" label-width="200px" size="mini" label-position="left">
      <div class="taskCreate-top">
        <el-form-item>
          <template v-slot:label>
            <div class="input-label">
              {{ $lang('task.taskGroup', '任务分组') }}
              <span style="color:#F56C6C">*</span>
            </div>
          </template>
          <el-select
            style="width:710px"
            v-model="createTaskData.GroupId"
            :placeholder="$lang('task.selectTaskGroup', '请选择任务分组')"
            clearable
          >
            <el-option
              :label="item.GroupName"
              :value="item.Id"
              v-for="(item, index) of TaskListGetter"
              :key="index"
            ></el-option>
          </el-select>
          <i
            class="el-icon-plus add-group-icon"
            @click="openAddGroup"
            :title="$lang('task.addGroup', '添加分组')"
          ></i>
        </el-form-item>
        <el-form-item>
          <template v-slot:label>
            <div class="input-label">
              {{ $lang('task.taskName', '任务名称') }}
              <span style="color:#F56C6C">*</span>
            </div>
          </template>
          <el-input
            style="width:800px;"
            :placeholder="$lang('task.taskNameInputTip', '请输入任务名称')"
            v-model="createTaskData.TaskName"
          ></el-input>
        </el-form-item>

        <div v-show="step === 'selectKeyword'">
          <div class="change-wrap">
            <el-form-item>
              <template v-slot:label>
                <div class="input-label">
                  {{ $lang('task.selectKeyword', '选择关键词') }}
                  <span style="color:#F56C6C">*</span>
                </div>
              </template>
              <div class="change-box">
                <div class="change-box-tit">
                  <wml-tip
                    :simple-tip="$lang('task.aboutKeywordSimpleTip', '相关推荐关键词')"
                    :detailTip="$lang('task.aboutKeywordDetailTip', '系统推荐的搜索关键词，将会根据该关键词进行数据检索')"
                  ></wml-tip>
                </div>
                <div class="change-content-box">
                  <div class="change-content-tit">
                    <el-checkbox
                      style="margin-right:10px;flex-shrink:0"
                      :indeterminate="isIndeterminateKeyword"
                      v-model="allCheckKeyword"
                      @change="handleCheckAllKeyword"
                    ></el-checkbox>
                    <span style="flex-shrink:0;">{{ $lang('task.selectAfterKerword', '已选关键词：') }}</span>
                    <span
                      style="color:#0F97FF;font-weight:700;flex-grow:1"
                    >{{createTaskData.KeyWord|filtersKeyWord}}</span>
                    <span class="add-keyword-box">
                      <i
                        class="el-icon-plus"
                        :title="$lang('task.addKeyword', '添加关键词选项及选项')"
                        @click="keywordDialogShow = !keywordDialogShow"
                      ></i>
                    </span>
                  </div>
                  <div class="change-content" ref="keyword-option-box" style="flex-grow:1">
                    <el-checkbox-group
                      v-model="createTaskData.KeyWord"
                      @change="handleCheckedKeywordChange"
                    >
                      <div
                        class="change-option"
                        v-for="(item, index) of keywordOption"
                        :key="index"
                      >
                        <el-checkbox :label="item.Label">{{item.Label}}</el-checkbox>
                      </div>
                    </el-checkbox-group>
                  </div>
                </div>
              </div>
            </el-form-item>
          </div>
          <div class="btn-wrap">
            <el-form-item>
              <div class="btn-box">
                <el-button
                  type="primary"
                  @click="goSelectArea"
                >{{$lang('task.nextArea', '下一步：选择区域')}}</el-button>
              </div>
            </el-form-item>
          </div>
        </div>

        <div v-show="step === 'selectArea'">
          <div class="change-wrap">
            <el-form-item>
              <template v-slot:label>
                <div class="input-label">
                  {{ $lang('task.selectArea', '选择区域') }}
                  <span style="color:#F56C6C">*</span>
                </div>
              </template>
              <div class="change-box">
                <div class="change-box-tit">
                  <wml-tip
                    :simple-tip="$lang('task.aboutAreaSimpleTip', '相关区域')"
                    :detailTip="$lang('task.aboutAreaDetailTip', '系统将会根据选择区域搜索对应地区的数据')"
                  ></wml-tip>
                </div>
                <div class="change-content-box" v-loading="areaLoading">
                  <div class="change-content-tit">
                    <el-checkbox
                      style="margin-right:10px;flex-shrink:0"
                      :indeterminate="isIndeterminate"
                      v-model="allCheckArea"
                      @change="handleCheckAllChange"
                    ></el-checkbox>
                    <span style="flex-shrink:0;">{{ $lang('task.afterSelectArea', '已选区域：') }}</span>
                    <span
                      style="color:#0F97FF;font-weight:700;flex-grow:1"
                    >{{ createTaskData.CountryCode|filterCountryCode(countryOption) }}</span>
                  </div>
                  <el-checkbox-group
                    v-model="createTaskData.CountryCode"
                    style="height:100%;overflow:auto"
                    @change="handleCheckedCitiesChange"
                  >
                    <div class="change-content select-area-box">
                      <div
                        class="change-option select-area-option"
                        v-for="(item, index) of countryOption"
                        :key="index"
                      >
                        <el-checkbox
                          :label="item.CountryCode"
                          :disabled="!temporaryCountry.includes(item.CountryCode)"
                        >
                          <!-- <img
                            style="width:30px;vertical-align:middle;border:1px solid #E7E7E7"
                            :src="require(`@/assets/image/national/${item.CountryCode}.jpg`)"
                          />-->
                          <img
                            style="width:30px;vertical-align:middle;border:1px solid #E7E7E7"
                            :src="`./national/${item.CountryCode}.jpg`"
                          />
                          <span
                            style="vertical-align:middle;margin-left:10px;color:#606266"
                          >{{item.ChineseName}}</span>
                        </el-checkbox>
                      </div>
                    </div>
                  </el-checkbox-group>
                </div>
              </div>
            </el-form-item>
          </div>
          <div class="btn-wrap">
            <el-form-item>
              <div class="btn-box">
                <el-button
                  type="primary"
                  @click="step = 'selectKeyword'"
                >{{ $lang('task.lastAboutKeyword', '上一步：相关推荐关键词') }}</el-button>
                <el-button
                  type="primary"
                  @click="goDelKeyword"
                >{{ $lang('task.nextFilterKeyword', '下一步：排除关键词') }}</el-button>
              </div>
            </el-form-item>
          </div>
        </div>

        <div v-show="step === 'delKeyword'">
          <div class="change-wrap">
            <el-form-item>
              <template v-slot:label>
                <div class="input-label">{{ $lang('task.removeKeyword', '排除关键词') }}</div>
              </template>
              <div class="change-box">
                <div class="change-box-tit">
                  <wml-tip
                    :simple-tip="$lang('task.removeKeywordSimpleTip', '排除关键词')"
                    :detailTip="$lang('task.removeKeywordDetailTip', '搜索过程中将会过滤排除关键字的搜索结果,排除关键词词组总数不应大于32')"
                  ></wml-tip>
                </div>
                <div class="change-content-box">
                  <div class="change-content-tit dey-key-tit">
                    <div>{{$lang('task.addRemoveKeywoed', '添加的关键词')}}</div>
                    <div>
                      <i class="el-icon-plus" @click="removeDialogShow = true"></i>
                      <i class="el-icon-delete" @click="delRemoveKey('all')"></i>
                    </div>
                  </div>
                  <div class="change-content" ref="removekey-box">
                    <div
                      v-for="(item, index) of createTaskData.RemoveKeyword"
                      :key="index"
                      class="del-option"
                    >
                      <div class="del-keyword">{{item}}</div>
                      <div class="del-option-action">
                        <i class="el-icon-delete" @click="delRemoveKey('once',item, index)"></i>
                      </div>
                    </div>
                    <!-- <el-checkbox-group v-model="createTaskData.RemoveKeyword">
                      <div
                        class="change-option"
                        v-for="(item, index) of removeKeywordOption"
                        :key="index"
                      >
                        <el-checkbox :label="item.Label">{{item.Label}}</el-checkbox>
                      </div>
                    </el-checkbox-group>-->
                  </div>
                </div>
              </div>
            </el-form-item>
          </div>

          <div class="btn-wrap">
            <el-form-item>
              <div class="btn-box">
                <el-button
                  type="primary"
                  @click="step = 'selectArea'"
                >{{ $lang('task.lastSelectArea', '上一步：选择区域') }}</el-button>
                <el-button type="primary" @click="createTask">{{ $lang('task.createNow', '立即创建') }}</el-button>
              </div>
            </el-form-item>
          </div>
        </div>
      </div>
    </el-form>
    <wml-dialog
      :visible.sync="removeDialogShow"
      :title="$lang('task.addRemoveKeywordTit', '增加排除关键词')"
      :drag="true"
      width="380px"
    >
      <el-form ref="form">
        <el-form-item>
          <el-input
            v-model="removeKeyword"
            type="textarea"
            clearable
            :placeholder="$lang('task.addRemoveKeywordTip', '请输入要增加的排除关键词,多个排除关键词之间需要换行,并且排除关键词词组总数不应大于32')"
            rows="8"
            size="mini"
          ></el-input>
        </el-form-item>
        <div style="text-align:center">
          <el-button
            style="padding-left:60px;padding-right:60px"
            type="primary"
            size="mini"
            :disabled="removeKeyword ==''"
            @click="addRemoveKey"
          >{{ $lang('task.ensure', '确定') }}</el-button>
        </div>
      </el-form>
    </wml-dialog>
    <wml-dialog
      :visible.sync="keywordDialogShow"
      :title="$lang('task.addKeywordTitle', '增加自定义关键词')"
      :drag="true"
      width="380px"
    >
      <el-form ref="form">
        <el-form-item>
          <el-input
            v-model="keyWordCustom"
            type="textarea"
            clearable
            :placeholder="$lang('task.addKeywordInputTip', '请输入要增加的关键词,多个关键词之间需要换行')"
            rows="8"
            size="mini"
          ></el-input>
        </el-form-item>
        <div style="text-align:center">
          <el-button
            style="padding-left:60px;padding-right:60px"
            type="primary"
            size="mini"
            :disabled="keyWordCustom ==''"
            @click="addKeywordCustom"
          >{{ $lang('task.ensure', '确定') }}</el-button>
        </div>
      </el-form>
    </wml-dialog>
  </div>
</template>
<script>
import { mapGetters, mapActions } from 'vuex'
export default {
  name: 'taskCreate',
  inject: [
    // 接收祖先组件注入的依赖（打开分组弹窗的方法）
    'openAddGroup'
  ],
  data () {
    return {
      step: 'selectKeyword',
      createTaskData: {
        GroupId: '',
        TaskName: '',
        KeyWord: [],
        CountryCode: [],
        RemoveKeyword: []
      },
      removeKeyword: '',
      removeDialogShow: false,
      keyword: this.$route.query.keyword,
      keywordOption: this.$route.query.keywordOption,
      countryOption: [],
      // removeKeywordOption: [],
      loading: false,
      areaLoading: false,
      // 暂时启用的国家
      temporaryCountry: ['uk', 'ph', 'sg', 'de', 'ca', 'us'],
      keywordDialogShow: false,
      keyWordCustom: '',
      allCheckArea: false,
      isIndeterminate: false,
      allCheckKeyword: false,
      isIndeterminateKeyword: false
      // removeKWLoading: false
    }
  },
  computed: {
    /**
     * @author: vince.Liang
     * @function: 获取vuex中的任务分组列表
     * @param {type}
     * @return:
     */
    ...mapGetters(['TaskListGetter'])
  },

  methods: {
    ...mapActions(['taskDetailInfoDispatch']),
    handleCheckAllKeyword (val) {
      this.createTaskData.KeyWord = []
      if (val) {
        for (let item of this.keywordOption) {
          this.createTaskData.KeyWord.push(item.Label)
        }
      }
      this.isIndeterminateKeyword = false
    },
    handleCheckedKeywordChange (value) {
      let checkedCount = value.length
      this.allCheckKeyword = checkedCount === this.keywordOption.length
      this.isIndeterminateKeyword = checkedCount > 0 && checkedCount < this.keywordOption.length
    },
    handleCheckAllChange (val) {
      this.createTaskData.CountryCode = val ? this.temporaryCountry : []
      this.isIndeterminate = false
    },
    handleCheckedCitiesChange (value) {
      let checkedCount = value.length
      this.allCheckArea = checkedCount === this.temporaryCountry.length
      this.isIndeterminate = checkedCount > 0 && checkedCount < this.temporaryCountry.length
    },

    /**
    * @author: vince.Liang
    * @function: 切换选择框到选择国家地区选项并加载对应选项
    * @param none
    * @return:undefined
    */
    goSelectArea () {
      if (this.createTaskData.KeyWord.length === 0) {
        this.$WmlMsg(this.$lang('task.mustSelectKeyword', '关键词必须选择'), 'warning')
        return
      }
      this.areaLoading = true
      this.SharpObj.getAllCountry(res => {
        res = JSON.parse(res)
        this.areaLoading = false
        if (res.Code === 0) {
          this.countryOption = res.Data
          this.step = 'selectArea'
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
    },

    /**
    * @author: vince.Liang
    * @function: 切换选择框到排除关键词选项并加载对应选项
    * @param none
    * @return:undefined
    */
    goDelKeyword () {
      if (this.createTaskData.CountryCode.length === 0) {
        this.$WmlMsg(this.$lang('task.mustSelectArea', '必须选择相关区域！'), 'warning')
        return
      }
      this.removeKWLoading = true
      this.SharpObj.getRemovedKW(this.keyword, res => {
        res = JSON.parse(res)
        this.removeKWLoading = false
        if (res.Code === 0) {
          this.createTaskData.RemoveKeyword = []
          for (let item of res.Data) {
            this.createTaskData.RemoveKeyword.push(item.Label)
          }
          this.step = 'delKeyword'
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
    },

    /**
  * @author: vince.Liang
  * @function: 确定创建任务具体逻辑
  * @data: 2019-3-27
  * @param none
  * @return:undefined
  */
    async createTask () {
      if (this.createTaskData.GroupId === '') {
        this.$WmlMsg(this.$lang('task.taskGroupNoNull', '任务分组不能为空！'), 'warning')
        return
      }
      if (this.createTaskData.TaskName === '') {
        this.$WmlMsg(this.$lang('task.taskNameNoNull', '任务名称不能为空！'), 'warning')
        return
      }
      if (this.createTaskData.RemoveKeyword.length > 32) {
        this.$WmlMsg(this.$lang('task.removeKeywordNo32', '排除关键词词组数量不应大于32'), 'warning')
        return
      }
      if (!await this.$WmlConfirm(`${this.$lang('task.createTaskConfirm0', '此操作将创建')} ${this.createTaskData.TaskName} ${this.$lang('task.createTaskConfirm1', '任务')}`)) { return }
      this.loading = true
      let data = { ...this.createTaskData }
      this.SharpObj.newTask(JSON.stringify(data), res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          for (let item of this.TaskListGetter) {
            if (item.Id === res.Data.GroupId) {
              this.taskDetailInfoDispatch({ groupName: item.GroupName, taskName: res.Data.TaskName })
              item.Task.push(res.Data)
              break
            }
          }
          this.loading = false
          this.$WmlMsg(`${this.$lang('task.createTaskSuccess0', '创建')} ${res.Data.TaskName} ${this.$lang('task.createTaskSuccess1', '任务成功！')}`)
          this.$to({ path: '/marketing/index/' + res.Data.Id })
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
    },

    /**
  * @author: vince.Liang
  * @function: 删除已经选择的排除关键字
  * @param {String} type 标识，判断是删除全部还是删除单条数据
  * @param {String} item 当前操作的数据
  * @param {Number} index 当前操作的数据位置
  * @return:undefined
  */
    async delRemoveKey (type, item, index) {
      if (type === 'all') {
        if (!await this.$WmlConfirm(this.$lang('task.deleteAllRemoveKeyword', '此操作将删除所有已经选择的排除关键字?'))) { return }
        this.createTaskData.RemoveKeyword = []
      }
      if (type === 'once') {
        if (!await this.$WmlConfirm(`${this.$lang('task.deleteSelectAfterRemoveKeywordConfirmTip', '此操作将删除已经选择的排除关键字')} ${item}`)) { return }
        this.createTaskData.RemoveKeyword.splice(index, 1)
      }
    },

    /**
  * @author: vince.Liang
  * @function: 确定添加排除关键词操作
  * @param none
  * @return:undefined
  */
    addRemoveKey () {
      this.createTaskData.RemoveKeyword.push(...this.removeKeyword.split(/\n/))
      this.$nextTick(() => {
        let el = this.$refs['removekey-box']
        if (el.scrollHeight > el.clientHeight) {
          el.scrollTop = el.scrollHeight - el.clientHeight
        }
      })
      this.removeDialogShow = false
    },

    /**
  * @author: vince.Liang
  * @function: 确定添加自定义关键词操作
  * @param none
  * @return:undefined
  */
    addKeywordCustom () {
      let keyWordCustom = this.keyWordCustom.split(/\n/)
      keyWordCustom = keyWordCustom.filter((item, index) => {
        if (item === '' || keyWordCustom.indexOf(item) !== index) {
          return false
        } else {
          return true
        }
      })
      let keywordArray = []
      for (let Label of keyWordCustom) {
        for (let keywordOption of this.keywordOption) {
          if (keywordOption.Label === Label) {
            this.$WmlMsg(`${this.$lang('task.keywordExit0', '关键词选项')} ${Label} ${this.$lang('task.keywordExit1', '已经存在！')}`, 'warning')
            return
          }
        }
        keywordArray.push({ Label })
      }
      this.keywordOption.push(...keywordArray)
      this.createTaskData.KeyWord.push(...keyWordCustom)
      this.keywordDialogShow = false
      this.keyWordCustom = ''
      this.$nextTick(() => {
        let el = this.$refs['keyword-option-box']
        if (el.scrollHeight > el.clientHeight) {
          el.scrollTop = el.scrollHeight - el.clientHeight
        }
      })
    }
  },
  filters: {
    /**
  * @author: vince.Liang
  * @function: 根据当前选择的国家的简称过滤出中文名并且拼接
  * @param {Array} val 当前选择的国家的简称数组
  * @param {Array} countryOption 国家列表数据
  * @return: String 拼接好的选择的当前国家的中文名
  */
    filterCountryCode (val, countryOption) {
      let country = ''
      for (let item of val) {
        for (let countryItem of countryOption) {
          if (countryItem.CountryCode === item) {
            country = country + countryItem.ChineseName + '、'
            break
          }
        }
      }
      return country.substr(0, country.length - 1)
    },

    /**
     * @author: vince.Liang
     * @function: 根据当前选择的关键字数组拼接
     * @param {Array} 当前选择的关键字数组
     * @return: String 拼接好的选择显示的关键字
     */
    filtersKeyWord (val) {
      let keyWord = ''
      for (let item of val) {
        keyWord = keyWord + item + '、'
      }
      return keyWord.substr(0, keyWord.length - 1)
    }
  },
  watch: {
    removeDialogShow (val) {
      val === false && (this.removeKeyword = '')
    }
  },
  mounted () {
    // 创建任务组成功自动选择该任务组
    this.$bus.$on('selectGroup', id => {
      this.createTaskData.GroupId = id
    })
  }
}
</script>
<style scoped>
.taskCreate-main {
  width: 100%;
  height: 100%;
}

.input-label {
  text-align: center;
}

.taskCreate-top >>> .el-input__inner {
  border-radius: 0;
}

.create-task-box {
  padding-top: 30px;
}

.change-wrap {
  padding-top: 30px;
}

.change-box-tit {
  padding: 0 18px;
  height: 40px;
  line-height: 40px;
  border: 1px solid #e7e7e7;
  border-bottom-color: #fff;
  display: inline-block;
  transform: translateY(1px);
  font-weight: 700;
}

.change-content-box {
  width: 800px;
  height: 440px;
  border: 1px solid #e7e7e7;
  display: flex;
  flex-direction: column;
}

.change-content-tit {
  /* height: 40px; */
  /* line-height: 40px; */
  border-bottom: 1px solid #e7e7e7;
  background-color: #fafafa;
  padding: 0 20px;
  font-size: 12px;
  flex-shrink: 0;
  padding: 6px 18px;
  display: flex;
}

.change-content {
  overflow: auto;
  height: calc(100% - 40px);
}

.change-option {
  padding: 0 18px;
  height: 30px;
  line-height: 30px;
  font-family: Arial, Helvetica, sans-serif;
}

.change-option >>> .el-checkbox__label,
.change-option >>> .el-radio__label {
  font-weight: 700;
  letter-spacing: 1px;
}

.del-option {
  width: 100%;
  display: flex;
  align-items: center;
  /* flex-wrap: wrap; */
  padding: 0 18px;
  justify-content: space-between;
}

.del-option:hover {
  background-color: rgba(64, 158, 255, 0.3);
}

.del-keyword {
  flex-grow: 1;
  margin-right: 100px;
}

.del-option-action {
  flex-shrink: 0;
}

.del-option-action i {
  cursor: pointer;
  font-size: 16px;
}

.del-option-action i:hover {
  color: #409eff;
}

.btn-box {
  width: 100%;
}

.btn-box >>> .el-button {
  padding-left: 60px;
  padding-right: 60px;
  border-radius: 0;
}

.select-area-box {
  display: flex;
  flex-wrap: wrap;
  height: 100%;
}

.select-area-option {
  width: 33%;
}

.taskCreate-main >>> .el-radio__inner {
  width: 16px;
  height: 16px;
}

.dey-key-tit {
  display: flex;
  justify-content: space-between;
}

.dey-key-tit i {
