<template>
  <div class="task-main">
    <div class="task-nav-wrap">
      <div class="task-nav-option" :class="{'task-nav-active': type === 'create'}">
        <div class="task-nav-content" @click="type = 'create'">
          <div class="nav-img-box">
            <img
              :src="type === 'create' ? './image/taskNavLeftActive.png' : './image/taskNavLeft.jpg'"
              alt
            />
          </div>
          <div class="nav-tit-box">
            <div class="nav-tit">{{ $lang('task.createMarketingTask', '创建自动化营销任务') }}</div>
            <div class="nav-desc">{{ $lang('task.createMarketingTaskTip', '通过产品核心关键词，自动获取客户联系方式，并营销触达') }}</div>
          </div>
        </div>
      </div>
      <div class="task-nav-option" :class="{'task-nav-active': type === 'import'}">
        <div class="task-nav-content" @click="type = 'import'">
          <div class="nav-img-box">
            <img
              :src="type === 'import' ?  './image/taskNavRightActive.png' : './image/taskNavRight.png'"
              alt
            />
          </div>
          <div class="nav-tit-box">
            <div class="nav-tit">{{ $lang('task.importCustomerWeb', '导入已有客户网站') }}</div>
            <div class="nav-desc">{{ $lang('task.importCustomerWebTip', '导入客户网站一级域名，更加快速进行精准营销') }}</div>
          </div>
        </div>
      </div>
    </div>

    <div class="task-content-wrap">
      <component  :is="component"></component>
    </div>
  </div>
</template>

<script>
import taskCreate from './components/taskCreate.vue'
import taskImport from './components/taskImport'
export default {
  name: 'task_index',
  components: { taskCreate, taskImport },
  data () {
    return {
      type: 'create'

    }
  },
  computed: {
    /**
     * @author: vince.Liang
     * @function: 根据type值动态切换组件
     * @data: 2019-3-27
     * @param {type}
     * @return:
     */
    component: function () {
      if (this.type === 'create') {
        return 'taskCreate'
      } else if (this.type === 'import') {
        return 'taskImport'
      }
      return ''
    }
  }

}
</script>

<style scoped>
.task-main {
  width: 100%;
  height: 100%;
  background-color: #efefec;
  display: flex;
  flex-direction: column;
}

.task-nav-wrap {
  width: 100%;
  display: flex;
  justify-content: space-between;
  padding-top: 10px;
  width: 100%;
  flex-shrink: 0;
}

.task-nav-option {
  width: 49.5%;
  padding: 0 0 10px 0;
  /* border: 1px solid #efefec; */
  border-bottom: 0;
}

.task-nav-content {
  width: 100%;
  height: 100%;
  display: flex;
  padding: 10px 0;
  background-color: #fff;
}

.nav-img-box {
  padding: 0 20px;
}

.nav-tit {
  font-size: 16px;
  height: 30px;
  line-height: 30px;
  color: #b2a9a9;
}

.nav-desc {
  font-size: 12px;
  color: #888888;
}

.task-nav-active {
  background-color: #fff;
  /* border-top: 1px solid #46abf9;
  border-left: 1px solid #cccccc;
  border-right: 1px solid #cccccc; */
}

.task-nav-active .nav-tit {
  color: #0d97fd;
  font-weight: 700;
}

.task-content-wrap {
  flex-grow: 1;
  overflow: auto;
  background-color: #fff;
  /* border: 1px solid #c8c8c8; */
  border-top: 0;
  padding-top: 30px;
}
</style>
